#!/bin/sh
#
# pkgbuild.sh: build and roll one package from its package directory.
#
# MIT licence, see LICENSE at the top of the repository.
#
#     sh build/pkg/pkgbuild.sh <package dir>
#
# The package directory holds package.sh (the metadata, assignments only),
# an optional build.sh (hooks only), the hand-written prototype, patches/,
# tests/ and README.md; see build/pkg/README.md. package.sh is checked and
# pkginfo is generated by pkgmeta; STYLE picks styles/<STYLE>.sh, which
# configures and runs make. The source is the tarball at URL, checked
# against SHA256, or, with neither set, a copy of the package's src/ (or of
# SRCPKG's src/).
#
# The harness: the build environment (amix-env.sh, gcc14-env.sh), the
# fetcher (fetch.sh), the gates (gates.sh) and the roll (pkgroll.sh,
# onever.sh). It is build/pkg/common, where layout.sh tells it where this
# checkout keeps the toolchains, pkgtools and the build output (out/pkg).
# AMIX_PKG_COMMON names another one; an amix-packages recipes/common finds
# its repository and siblings itself, as it always has. Hooks see the
# harness as $COMMON and the repository as $REPO.
#
# Hooks a build.sh may define (sourced after the environment):
#   configure_args     echo extra ./configure arguments
#   pre_configure      export configure seeds (ac_cv_...)
#   post_configure     assert config.h answers (cwd: tree)
#                      (the three run in STYLE=configure only)
#   make_args          echo extra make arguments or targets
#   build              STYLE=hooks only: configure and build (cwd: tree),
#                      every real compile line into $BUILD/make.log
#   post_build         assert the build (cwd: tree)
#   stage              copy the payload into $DEST (cwd: tree); binaries
#                      unstripped, the driver gates and strips them
# Variables a build.sh may set (default empty):
#   EXTRA_CFLAGS       added to the CFLAGS of configure and make
#   MAKE_CFLAGS        added to make's CFLAGS only; `-include
#                      $AMIX_GCC14_DECLS' belongs here, since in configure it
#                      collides with autoconf's `char f();' probes
#   ASM_REVIEWED       why imported .s/.S files are acceptable (else a failure)
#   ZERO_OK            payload paths allowed to be empty files (else a
#                      failure: a cross build's config/missing leaves a
#                      regenerated man page or info file empty, exit 0)
#
# Outputs: $AMIX_BUILD_ROOT/<NAME>/{src,work,dest,pkgwork,*.log,BUILD.txt}
# and $AMIX_BUILD_ROOT/pkg/<PKG>-<VERSION>-<PKGREV>.pkg.

set -e

[ $# -eq 1 ] && [ -f "$1/package.sh" ] || {
	echo "usage: sh build/pkg/pkgbuild.sh <package dir>" >&2
	exit 2
}
HERE=$(cd "$1" && pwd)
PKGDIR=$(cd "$(dirname "$0")" && pwd)
TOP=$(cd "$PKGDIR/../.." && pwd)
COMMON=${AMIX_PKG_COMMON:-$PKGDIR/common}
[ -f "$COMMON/amix-env.sh" ] || {
	echo "[FAIL] no harness: $COMMON has no amix-env.sh" >&2
	echo "       unset AMIX_PKG_COMMON for build/pkg/common, or name a harness" >&2
	exit 2
}
COMMON=$(cd "$COMMON" && pwd)
if [ "$COMMON" = "$(cd "$COMMON/../.." && pwd)/recipes/common" ]; then
	REPO=$(cd "$COMMON/../.." && pwd)     # amix-env.sh's AMIX_REPO_ROOT
	LAYOUT=amix-packages
else
	REPO=$TOP
	LAYOUT=amix
	AMIX_TOP=$TOP AMIX_PKG_COMMON=$COMMON
	. "$PKGDIR/layout.sh"
fi

# --- package.sh -----------------------------------------------------------------
python3 -I "$PKGDIR/pkgmeta" check "$HERE" >/dev/null
STYLE=configure TOOLCHAIN=gcc14 PREFIX=/opt/amix DEPENDS= BUILD_DEPENDS= SRCDIR= PATCH_STRIP=1
URL= SHA256= SRCPKG= APKG_DESC= CONFFILES= SYSTEM_PATHS= ESSENTIAL=no STOCK_ETC=
. "$HERE/package.sh"
SRCDIR=${SRCDIR:-$NAME-$VERSION}
if [ -n "$SRCPKG" ]; then
	SRCTREE=$(cd "$HERE/../$SRCPKG/src" && pwd)
elif [ -z "$URL" ]; then
	SRCTREE=$HERE/src
else
	SRCTREE=
fi
PKGVERSION=$VERSION-$PKGREV

# --- environment, style and hooks -------------------------------------------------
export AMIX_PREFIX="$PREFIX"
export TOOLCHAIN
AMIX_RECIPE_TOOLCHAINS=$TOOLCHAIN
. "$COMMON/amix-env.sh"
. "$COMMON/fetch.sh"
. "$COMMON/pkgroll.sh"
. "$COMMON/gates.sh"
. "$PKGDIR/styles/$STYLE.sh"
EXTRA_CFLAGS= MAKE_CFLAGS= ASM_REVIEWED= ZERO_OK=
configure_args() { :; }
make_args() { :; }
pre_configure() { :; }
post_configure() { :; }
post_build() { :; }
stage() { echo "[FAIL] build.sh defines no stage hook" >&2; exit 1; }
[ -f "$HERE/build.sh" ] && . "$HERE/build.sh"
if [ "$LAYOUT" = amix ]; then
	# one gcc14 pin: the harness's must be toolchain/'s
	if [ "$AMIX_TOOLCHAIN" = gcc14 ] && [ "${AMIX_GCC14_COMMIT:-}" != "$AMIX_G14_PIN" ]; then
		echo "[FAIL] the harness pins gcc14-cross-amix ${AMIX_GCC14_COMMIT:-<none>}," >&2
		echo "       toolchain/gcc14-cross-amix.pin $AMIX_G14_PIN" >&2
		exit 1
	fi
	# and the period one, when it is a checkout (the container's is a copy
	# made from the pin)
	if [ "$AMIX_TOOLCHAIN" = period ] && [ -n "${GCA:-}" ] &&
	   _gca=$(git -C "$GCA/.." rev-parse --show-toplevel 2>/dev/null) &&
	   [ "$_gca" = "$(cd "$GCA/.." && pwd -P)" ]; then
		_gca=$(git -C "$_gca" rev-parse HEAD)
		[ "$_gca" = "$AMIX_GCA_PIN" ] || {
			echo "[FAIL] the period toolchain $GCA is gcc-cross-amix $_gca," >&2
			echo "       toolchain/gcc-cross-amix.pin $AMIX_GCA_PIN" >&2
			exit 1
		}
	fi
	[ -x "$AMIX_PKGMK" ] && [ -x "$AMIX_PKGTRANS" ] || {
		echo "[FAIL] no host pkgmk/pkgtrans ($AMIX_PKGMK, $AMIX_PKGTRANS);" >&2
		echo "       build them: (cd userland/pkgtools/heirloom && ./build-host.sh)" >&2
		exit 1
	}
fi

BUILD="$AMIX_BUILD_ROOT/$NAME"
SRC="$BUILD/src"
WORKDIR="$BUILD/work"
TREE="$WORKDIR/$SRCDIR"
DEST="$BUILD/dest"
PKGOUT="$AMIX_BUILD_ROOT/pkg"
export HERE BUILD TREE DEST

echo "=== $NAME $PKGVERSION ($PKG, $CATEGORY, set $SET, style $STYLE) ==="
amix_env_banner
echo
mkdir -p "$SRC" "$WORKDIR" "$PKGOUT"

# --- 1. the source: fetched and verified before extraction, or copied -----------------
echo "--- source ---"
rm -rf "$TREE"
if [ -n "$SRCTREE" ]; then
	# in the tree: the commit pins it; the digest is for the record
	mkdir -p "$TREE"
	cp -R "$SRCTREE/." "$TREE"
	SRCDIGEST=$(cd "$TREE" && find . -type f -print0 | LC_ALL=C sort -z | xargs -0r sha256sum | sha256sum | cut -c1-64)
	echo "  in-tree source ${SRCTREE#$TOP/}: $(cd "$TREE" && find . -type f | wc -l) files, digest $SRCDIGEST"
else
	TARBALL="$SRC/${URL##*/}"
	amix_fetch "$URL" "$SHA256" "$TARBALL"
	case "$TARBALL" in
	*.tar.gz|*.tgz) tar xzf "$TARBALL" -C "$WORKDIR" ;;
	*.tar.bz2)      tar xjf "$TARBALL" -C "$WORKDIR" ;;
	*.tar.xz)       tar xJf "$TARBALL" -C "$WORKDIR" ;;
	*) echo "[FAIL] unknown archive type: $TARBALL" >&2; exit 1 ;;
	esac
	[ -d "$TREE" ] || { echo "[FAIL] $TREE not produced by the tarball" >&2; exit 1; }
fi
echo

# --- 2. patches ----------------------------------------------------------------------
echo "--- patches ---"
for p in "$HERE"/patches/*.patch; do
	[ -f "$p" ] || continue
	echo "  applying $(basename "$p")"
	( cd "$TREE" && patch -p"$PATCH_STRIP" --batch --fuzz=0 < "$p" ) || {
		echo "[FAIL] patch $(basename "$p") did not apply cleanly" >&2; exit 1; }
done
if ! amix_gate_noasm "$TREE"; then
	[ -n "$ASM_REVIEWED" ] || { echo "[FAIL] assembly in the tree and no ASM_REVIEWED" >&2; exit 1; }
	echo "  ASM reviewed: $ASM_REVIEWED"
fi
echo

cd "$TREE"
# --- 3. configure (the style's) ------------------------------------------------------
style_configure

# --- 4. build (strict) -------------------------------------------------------------------
echo "--- make ---"
if [ "${STYLE_LOG:-}" = own ]; then
	# the style writes make.log itself (styles/hooks.sh)
	: > "$BUILD/make.log"
	style_make
else
	style_make > "$BUILD/make.log" 2>&1 || {
		echo "[FAIL] make failed; see $BUILD/make.log" >&2
		tail -25 "$BUILD/make.log" >&2
		exit 1
	}
fi
if grep -E 'implicit declaration|pointer from integer|integer from pointer' "$BUILD/make.log" >/dev/null; then
	echo "[FAIL] implicit declarations or pointer/integer conversions in the build:" >&2
	grep -E 'implicit declaration|pointer from integer|integer from pointer' "$BUILD/make.log" | sort -u >&2
	exit 1
fi
echo "  no implicit declarations, no pointer/integer conversions"
if [ "$AMIX_TOOLCHAIN" = gcc14 ]; then
	amix_gate_g14_strict "$BUILD/make.log"
	amix_gate_g14_compat "$BUILD/make.log"
fi
post_build
echo

# --- 5. stage, then the prototype and the binaries ----------------------------------------
echo "--- stage ---"
rm -rf "$DEST"; mkdir -p "$DEST"
stage
# STOCK_ETC: stock defaults from amix-system's etc/, by path, each checked
# against system/MANIFEST.sha256 (they never enter this repository)
for p in $STOCK_ETC; do
	want=$(awk -v f="${p#/}" 'substr($0, 67) == f { print substr($0, 1, 64) }' "$TOP/system/MANIFEST.sha256")
	src="${AMIX_SYSTEM:-}/${p#/}"
	[ -n "${AMIX_SYSTEM:-}" ] && [ -f "$src" ] && [ ! -L "$src" ] || {
		echo "[FAIL] STOCK_ETC $p: no file $src; AMIX_SYSTEM names an amix-system" >&2
		echo "       checkout (system/fetch-amix-system)" >&2
		exit 1
	}
	got=$(sha256sum < "$src" | cut -c1-64)
	[ "$got" = "$want" ] || {
		echo "[FAIL] STOCK_ETC $p: $src is $got, system/MANIFEST.sha256 ${want:-<none>}" >&2
		exit 1
	}
	[ ! -e "$DEST$p" ] && [ ! -L "$DEST$p" ] || {
		echo "[FAIL] STOCK_ETC $p: the stage hook staged it too" >&2; exit 1; }
	mkdir -p "$(dirname "$DEST$p")"
	cp "$src" "$DEST$p"
	echo "  STOCK ok  $p (amix-system, sha256 $want)"
done
# the prototype is the payload: every f/d/s line staged, nothing staged unlisted
awk '$1 ~ /^[fdvesl]$/ && NF >= 3 { p = $3; sub(/=.*$/, "", p); print p }' "$HERE/prototype" | LC_ALL=C sort > "$BUILD/proto.list"
( cd "$DEST" && find . -mindepth 1 | sed 's|^\.||' ) | LC_ALL=C sort > "$BUILD/dest.list"
# a directory staged only as a parent of listed paths (/usr and /usr/bin under
# PREFIX=/usr/local) is the system's, not the package's: not compared
awk '{ p = $0; while (sub(/\/[^\/]*$/, "", p) && p != "") print p }' "$BUILD/proto.list" |
	LC_ALL=C sort -u | LC_ALL=C comm -23 - "$BUILD/proto.list" | LC_ALL=C comm -12 - "$BUILD/dest.list" |
	while read -r p; do
		if [ -d "$DEST$p" ] && [ ! -L "$DEST$p" ]; then echo "$p"; fi
	done > "$BUILD/dest.parents"
LC_ALL=C comm -23 "$BUILD/dest.list" "$BUILD/dest.parents" > "$BUILD/dest.check"
if ! LC_ALL=C comm -3 "$BUILD/proto.list" "$BUILD/dest.check" | grep . >/dev/null; then
	echo "  PROTO ok  $(grep -c . "$BUILD/proto.list") paths, prototype == staged tree$(
		[ ! -s "$BUILD/dest.parents" ] || echo " (and parent directories:" $(cat "$BUILD/dest.parents")")")"
else
	echo "[FAIL] prototype and staged tree differ (left: prototype only, right: staged only):" >&2
	LC_ALL=C comm -3 "$BUILD/proto.list" "$BUILD/dest.check" >&2
	exit 1
fi
for z in $( cd "$DEST" && find . -type f -size 0 | sed 's|^\.||' ); do
	case " $ZERO_OK " in *" $z "*) echo "  EMPTY ok  $z (ZERO_OK)" ;;
	*) echo "[FAIL] empty file in the payload: $z (regenerated by config/missing?)" >&2; exit 1 ;;
	esac
done
# the symbols a shared object on the box defines (sysroot copy); the period
# nm (binutils 2.8.1) has no -D for the stock libc.so.1, and under set -e
# its failure would end the list before the plain nm
dso_syms() {
	{ "$NM" -D "$1" || :; "$NM" "$1"; } 2>/dev/null | awk '$1 != "U" && NF >= 2 {print $NF}'
}
BINS=$(amix_gate_elfs "$DEST")
for b in $BINS; do
	# executables and shared objects only (ELF e_type 2/3): an archive keeps
	# its symbols and its members' undefined references
	case "$(od -An -tx1 -j16 -N2 "$b" | tr -d ' ')" in
	0002|0003) ;;
	*) echo "  ARCHIVE/OBJ $(basename "$b"): no undef gate, not stripped"; continue ;;
	esac
	amix_gate_elf "$b"
	# every undefined symbol must be defined by a shared object the binary
	# records as NEEDED (libc.so.1, or a bare name from the box's /usr/lib)
	libs=$("$OBJDUMP" -p "$b" | awk '$1 == "NEEDED" {print $2}' | tr '\n' ' ')
	files=""
	for n in $libs; do
		case $n in /*) l="$AMIX_SYSROOT$n" ;; *) l="$AMIX_SYSROOT/usr/lib/$n" ;; esac
		[ -f "$l" ] || { echo "[FAIL] $(basename "$b"): NEEDED $n not in the sysroot" >&2; exit 1; }
		files="$files $l"
	done
	for l in $files; do dso_syms "$l"; done | LC_ALL=C sort -u > "$BUILD/needed.syms"
	missing=$("$NM" -u "$b" | awk '{print $NF}' | LC_ALL=C sort -u | LC_ALL=C comm -23 - "$BUILD/needed.syms" | tr '\n' ' ')
	[ -z "$missing" ] || { echo "[FAIL] $(basename "$b"): undefined symbols no NEEDED library defines: $missing" >&2; exit 1; }
	echo "  UNDEF ok  $(basename "$b"): every undefined symbol is defined by its NEEDED: $libs"
	$STRIP "$b"
done
echo

# --- 6. pkginfo from package.sh, roll ----------------------------------------------------
echo "--- package ---"
WORK="$BUILD/pkgwork"
rm -rf "$WORK"; mkdir -p "$WORK"
python3 -I "$PKGDIR/pkgmeta" pkginfo "$HERE" > "$WORK/pkginfo"
cp "$HERE/prototype" "$WORK/prototype"
# Every time stamp of the datastream is SOURCE_DATE_EPOCH (the release's,
# from make dist or the build container); unset, the time of the last
# commit that changed the package directory.
if [ -z "${SOURCE_DATE_EPOCH:-}" ]; then
	SOURCE_DATE_EPOCH=$(git -C "$HERE" log -1 --format=%ct -- . 2>/dev/null) && [ -n "$SOURCE_DATE_EPOCH" ] || {
		echo "[FAIL] SOURCE_DATE_EPOCH is unset and $HERE has no commit to take it from" >&2
		exit 1
	}
fi
export SOURCE_DATE_EPOCH
echo "  epoch   SOURCE_DATE_EPOCH=$SOURCE_DATE_EPOCH"
amix_pkgroll "$WORK" "$DEST" "$PKG" "$PKGVERSION" "$PKGOUT/$PKG-$PKGVERSION.pkg"

{
	echo "$NAME $PKGVERSION ($PKG) toolchain $AMIX_TOOLCHAIN"
	[ -z "$SRCTREE" ] || echo "source ${SRCTREE#$TOP/} digest $SRCDIGEST"
	echo "pkg $PKGOUT/$PKG-$PKGVERSION.pkg md5 $(md5sum "$PKGOUT/$PKG-$PKGVERSION.pkg" | cut -d' ' -f1) size $(stat -c%s "$PKGOUT/$PKG-$PKGVERSION.pkg")"
	for b in $BINS; do
		echo "sum-r $(sum -r "$b" | awk '{print $1}') $(stat -c%s "$b") ${b#$DEST}"
	done
} > "$BUILD/BUILD.txt"
sed 's/^/  /' "$BUILD/BUILD.txt"
python3 -I "$PKGDIR/pkgmeta" catalog "$HERE" --pkg "$PKGOUT/$PKG-$PKGVERSION.pkg" > "$BUILD/catalog.line"
echo "  catalog: $(cat "$BUILD/catalog.line")"
echo
echo "=== $NAME $PKGVERSION built ==="
